CREATE TABLE IF NOT EXISTS ordering_entry_flows(tenant_id UUID NOT NULL,store_id UUID NOT NULL,device_id UUID NOT NULL,entry_flow_id TEXT NOT NULL,state TEXT NOT NULL,phase_revision BIGINT NOT NULL,policy_version TEXT NOT NULL,policy_result TEXT NOT NULL,policy_snapshot_json JSONB NOT NULL,ordering_session_id TEXT NOT NULL DEFAULT '',member_ref TEXT NOT NULL DEFAULT '',safe_reason TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,PRIMARY KEY(tenant_id,store_id,entry_flow_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_entry_flow_per_device ON ordering_entry_flows(tenant_id,store_id,device_id) WHERE state NOT IN ('menu_ready','abandoned');
CREATE TABLE IF NOT EXISTS ordering_sessions(tenant_id UUID NOT NULL,store_id UUID NOT NULL,ordering_session_id TEXT NOT NULL,entry_flow_id TEXT NOT NULL,status TEXT NOT NULL,member_ref TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL,closed_at TIMESTAMPTZ,PRIMARY KEY(tenant_id,store_id,ordering_session_id),UNIQUE(tenant_id,store_id,entry_flow_id));
CREATE TABLE IF NOT EXISTS ordering_entry_events(tenant_id UUID NOT NULL,store_id UUID NOT NULL,entry_flow_id TEXT NOT NULL,phase_revision BIGINT NOT NULL,event_type TEXT NOT NULL,payload_json JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(tenant_id,store_id,entry_flow_id,phase_revision));
